testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { aplicarEvento, listarDestinatarios } from './solution.mjs';

test('entrar e mensagem constroem o estado novo sem tocar no original', () => {
  const inicial = { participantes: [], mensagens: [] };
  const comAna = aplicarEvento(inicial, { tipo: 'entrar', nome: 'Ana' });
  const comBia = aplicarEvento(comAna, { tipo: 'entrar', nome: 'Bia' });
  const final = aplicarEvento(comBia, { tipo: 'mensagem', autor: 'Ana', texto: 'oi!' });

  assert.deepEqual(final.participantes, ['Ana', 'Bia']);
  assert.deepEqual(final.mensagens, [{ autor: 'Ana', texto: 'oi!' }]);
  assert.deepEqual(inicial, { participantes: [], mensagens: [] });
});

test('sair remove e entrar repetido não duplica', () => {
  let sala = aplicarEvento({ participantes: ['Ana', 'Bia'], mensagens: [] }, { tipo: 'sair', nome: 'Ana' });
  assert.deepEqual(sala.participantes, ['Bia']);
  sala = aplicarEvento(sala, { tipo: 'entrar', nome: 'Bia' });
  assert.deepEqual(sala.participantes, ['Bia']);
});

test('evento desconhecido lança erro', () => {
  assert.throws(
    () => aplicarEvento({ participantes: [], mensagens: [] }, { tipo: 'entrar_na_sala', nome: 'Ana' }),
    /desconhecido/,
  );
});

test('listarDestinatarios exclui o autor da transmissão', () => {
  const sala = { participantes: ['Ana', 'Bia', 'Caio'], mensagens: [] };
  assert.deepEqual(listarDestinatarios(sala, 'Ana'), ['Bia', 'Caio']);
  assert.deepEqual(listarDestinatarios({ participantes: [], mensagens: [] }, 'Ana'), []);
});

solutionCode:
export function aplicarEvento(estado, evento) {
  if (evento.tipo === 'entrar') {
    if (estado.participantes.includes(evento.nome)) return estado;
    return { ...estado, participantes: [...estado.participantes, evento.nome] };
  }

  if (evento.tipo === 'mensagem') {
    return {
      ...estado,
      mensagens: [...estado.mensagens, { autor: evento.autor, texto: evento.texto }],
    };
  }

  if (evento.tipo === 'sair') {
    return { ...estado, participantes: estado.participantes.filter((p) => p !== evento.nome) };
  }

  throw new Error('evento desconhecido');
}

export function listarDestinatarios(estado, autor) {
  return estado.participantes.filter((nome) => nome !== autor);
}
